"""The person key against goldens generated by the OLD ``services/identity.fold`` (review 012):
``python -m projectzero.ops.parity_people goldens``."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from projectzero.network.identity import fold
from projectzero.ops.parity_people import corpus

GOLDEN: dict[str, Any] = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_people_fold.json").read_text(
        encoding="utf-8"
    )
)


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"] == {"old_revision": "6c739b9cb6ca2517b845e381d39a36c50eccc59e", "old_dirty": False}


def test_the_golden_input_is_the_current_corpus() -> None:
    assert [c["value"] for c in GOLDEN["cases"]] == json.loads(json.dumps(corpus()))


@pytest.mark.parametrize("case", GOLDEN["cases"], ids=lambda c: repr(c["value"])[:40])
def test_fold_matches_the_old_code(case: dict[str, Any]) -> None:
    assert fold(case["value"]) == case["folded"]


def test_the_goldens_cover_the_rules() -> None:
    expected = {c["value"]: c["folded"] for c in GOLDEN["cases"] if isinstance(c["value"], str)}
    assert expected["Prof. Dr.-Ing. Hans Meier"] == "hans meier"  # stacked titles
    assert expected["Dipl.-Ing. Lena Weiß"] == "lena weiss"  # ß -> ss after the title
    assert expected["JÜRGEN GROẞ"] == "jurgen gross"  # capital ẞ
    assert expected["Dr.Ada Lovelace"] == "dr ada lovelace"  # a title needs a space after it
    assert expected["Jane Roe, PhD"] == "jane roe phd"  # only LEADING titles are stripped
    assert expected["李小龙"] == ""  # no ASCII letters: an empty key
